<?php
declare(strict_types=1); namespace App\Http\Controllers\Classrooms; use App\Http\Controllers\Controller; use App\Http\Requests\Classrooms\UpdateClassroomHomeroomRequest; use App\Models\{Classroom,Personnel}; use App\Services\Classrooms\ClassroomService; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
class ClassroomHomeroomController extends Controller {public function edit(Classroom $classroom):View{request()->user()->can('classrooms.assign-homeroom')?:abort(403);$personnel=Personnel::where('is_active',true)->where(fn($q)=>$q->where('position','like','%Guru%')->orWhere('position','like','%Kepala Madrasah%'))->get();return view('classrooms.homeroom',compact('classroom','personnel'));}public function update(UpdateClassroomHomeroomRequest $r,Classroom $classroom,ClassroomService $s):RedirectResponse{$s->assignHomeroom($r->user(),$classroom,$r->validated('homeroom_personnel_id'));return redirect()->route('classrooms.show',$classroom)->with('success','Wali kelas berhasil diperbarui.');}}
